/**
 * The Photoshop half of sync.
 *
 * # This is a CommonJS classic script, on purpose
 *
 * UXP has NO ES module support. No `import`, no `<script type="module">`. A
 * panel script that uses them does not raise a useful error -- it simply never
 * runs, and Photoshop shows an empty panel or none at all. That is the single
 * most common reason a UXP plugin "will not load", and it is what the first
 * version of this file got wrong. Everything arrives through `require()`.
 *
 * `plugin/vendor/` holds CommonJS conversions of `src/sync/`, generated by
 * `scripts/vendor-plugin.mjs` and guarded against drift by `test/sync.mjs`.
 * They are inside this folder because UXP treats the folder holding
 * `manifest.json` as the plugin root, and a plugin that reaches above it may
 * fail to load with no explanation.
 *
 * # Everything reports where a person can see it
 *
 * UXP's debugger is a separate tool that must be attached deliberately, so a
 * plugin that reports failures only to `console` reports them to nobody. Every
 * failure here -- including uncaught errors and rejected promises -- is
 * written to the panel's own log.
 *
 * # What is still assumed
 *
 * The seams that need a real Photoshop to confirm are marked `VERIFY:`. Each
 * one now LOGS what it actually received, so a single run turns the assumption
 * into a fact rather than into another guess.
 */

/* eslint-env browser */
/* global require, document, WebSocket, setTimeout, clearTimeout */

// --------------------------------------------------------------- the log

const MAX_LOG_LINES = 300;
const logLines = [];
let logbox = null;

function stamp() {
  const d = new Date();
  const pad = (n, w = 2) => String(n).padStart(w, '0');
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}.${pad(d.getMilliseconds(), 3)}`;
}

/**
 * One log line, on screen.
 *
 * Built with createElement rather than innerHTML: UXP's DOM is not a browser
 * DOM and its innerHTML support is not something to bet a diagnostic channel
 * on -- which is exactly the channel you need working when nothing else is.
 */
function log(level, ...parts) {
  const text = parts
    .map((p) => {
      if (typeof p === 'string') return p;
      try { return JSON.stringify(p); } catch { return String(p); }
    })
    .join(' ');
  const line = `${stamp()}  ${text}`;
  logLines.push({ level, line });
  if (logLines.length > MAX_LOG_LINES) logLines.shift();

  try { console.log(line); } catch { /* console may not exist */ }
  if (!logbox) return;

  const div = document.createElement('div');
  if (level !== 'info') div.className = `lvl-${level}`;
  div.textContent = line;
  logbox.appendChild(div);
  while (logbox.childNodes.length > MAX_LOG_LINES) logbox.removeChild(logbox.firstChild);
  logbox.scrollTop = logbox.scrollHeight;
}

const info = (...a) => log('info', ...a);
const warn = (...a) => log('warn', ...a);
const fail = (...a) => log('err', ...a);
const good = (...a) => log('ok', ...a);

/** Run something and log the failure rather than dying silently. */
function guard(what, fn) {
  try {
    return fn();
  } catch (e) {
    fail(`${what} threw:`, e && e.message ? e.message : String(e));
    if (e && e.stack) fail(String(e.stack).split('\n').slice(0, 3).join(' | '));
    return undefined;
  }
}

// ----------------------------------------------------------- host modules

let photoshop = null;
let app = null;
let action = null;
let uxpVersion = 'unknown';

function loadHost() {
  photoshop = require('photoshop');
  app = photoshop.app;
  action = photoshop.action;
  try { uxpVersion = require('uxp').versions.uxp; } catch { /* older builds */ }
  if (!app) throw new Error("require('photoshop').app is undefined");
  if (!action) throw new Error("require('photoshop').action is undefined");
}

// --------------------------------------------------------- shared modules

const { PAIR_CODE_ALPHABET, PAIR_CODE_LENGTH } = require('./vendor/protocol.js');
const { treeFrameFor, changeForNotification, coalesceEvents } = require('./vendor/photoshop.js');

const PLUGIN_VERSION = '0.2.0';

/**
 * How long a burst is allowed to accumulate before it is flushed.
 *
 * Photoshop fires notifications continuously during one gesture -- a drag is
 * dozens of `move`s, each superseding the last. 80 ms is below the point a
 * person reads as lag and well above one notification's spacing.
 */
const FLUSH_MS = 80;

/**
 * The notifications subscribed to, as PLAIN STRINGS.
 *
 * VERIFY-FIXED: the first version passed `[{event: 'set'}, ...]`. Adobe's own
 * documented form is a string array -- `addNotificationListener(['all'], cb)`
 * -- so the object form subscribed to nothing and no event ever arrived.
 */
const WATCHED = [
  'set', 'move', 'transform', 'free', 'reorder', 'delete', 'make', 'duplicate',
  'crop', 'canvasSize', 'paint', 'brushTool', 'eraserTool', 'gaussianBlur',
  'applyImage', 'hueSaturation', 'levels', 'curves', 'brightnessContrast',
  'setLayerEffects', 'disableLayerStyle',
];

// ------------------------------------------------------------------ state

const el = (id) => document.getElementById(id);
let ui = {};

let socket = null;
let paired = false;
let pending = [];
let flushTimer = null;
let listener = null;
let sentCount = 0;
/** change kind -> how many were skipped. Counted, not listed: one stroke is dozens. */
const skipped = new Map();
/** Raw descriptors already logged, so one drag does not print two hundred of them. */
const sampled = new Set();
/** Changes whose unreadable descriptor has already been printed once. */
const sampledPayload = new Set();

// ------------------------------------------------------------------- view

function setStatus(text, kind) {
  if (!ui.status) return;
  ui.status.textContent = text;
  ui.status.className = kind || '';
}

function showConnected(isConnected) {
  if (ui.setup) ui.setup.style.display = isConnected ? 'none' : 'block';
  if (ui.live) ui.live.style.display = isConnected ? 'flex' : 'none';
}

function clearChildren(node) {
  while (node && node.firstChild) node.removeChild(node.firstChild);
}

function renderSkipped() {
  if (!ui.unsynced) return;
  clearChildren(ui.unsynced);

  if (!skipped.size) {
    const li = document.createElement('li');
    li.className = 'empty';
    li.textContent = 'Nothing skipped yet.';
    ui.unsynced.appendChild(li);
    return;
  }
  skipped.forEach((count, change) => {
    const li = document.createElement('li');
    const what = document.createElement('span');
    what.className = 'what';
    what.textContent = change;
    li.appendChild(what);
    li.appendChild(document.createTextNode(` — ${count} change${count === 1 ? '' : 's'} not sent`));
    ui.unsynced.appendChild(li);
  });
}

function noteSkipped(change) {
  skipped.set(change, (skipped.get(change) || 0) + 1);
  renderSkipped();
}

// ----------------------------------------------------------- the document

/**
 * Photoshop's layer tree as plain objects.
 *
 * Reversed, because `doc.layers` is top-down -- index 0 is the TOPMOST layer
 * -- while `flattenLayerTree` documents that it expects bottom-to-top, since
 * everything in this repo reads `children[0]` as the bottom.
 *
 * VERIFY: `layer.bounds` on a group, and on a layer with effects. Some
 * versions report effect-inclusive bounds, which would not match the app's and
 * would drop those layers to a looser match tier. The shape is logged once, at
 * `Run diagnostics`, so this stops being a guess.
 */
/**
 * The layer's kind, as a string the shared matcher can read.
 *
 * `Layer.kind` returns a **LayerKind enum object**, not a string — so
 * `String(layer.kind)` can yield `[object Object]`, and every group would then
 * look like a raster layer and try to match one. Groups are therefore detected
 * STRUCTURALLY, by the presence of `layers`, which Adobe documents as existing
 * only on a group. That is the one classification that must not be wrong: a
 * group matching a real layer is a mis-mapped edit.
 *
 * Everything else falls back through the enum's likely shapes and finally to
 * an empty string, which the matcher reports rather than guesses at.
 */
function hostKind(layer) {
  if (layer.layers !== undefined && layer.layers !== null) return 'group';
  const k = layer.kind;
  if (k === undefined || k === null) return '';
  if (typeof k === 'string') return k;
  return String(k.name || k._value || k.value || '');
}

/**
 * The layer's bounds, WITHOUT layer effects.
 *
 * Adobe documents `Layer.bounds` as "bounds of the layer, INCLUDING the
 * effects". The app's bounds come from the PSD layer record, which is the
 * pixel rectangle with no effects in it — so on any layer carrying a drop
 * shadow, glow or stroke the two sides would disagree, the signature would not
 * match, and the layer would silently fail to sync.
 *
 * `boundsNoEffects` is the same rectangle with effects excluded, which is what
 * the app actually has. Falls back to `bounds` on a build that lacks it, and
 * `boundsUsed` records which so the diagnostics can say.
 */
let boundsUsed = null;

function hostBounds(layer) {
  if (layer.boundsNoEffects) {
    if (!boundsUsed) boundsUsed = 'boundsNoEffects';
    return layer.boundsNoEffects;
  }
  if (!boundsUsed) boundsUsed = 'bounds (NO boundsNoEffects on this build — layers with effects may not match)';
  return layer.bounds;
}

function hostLayers(layers) {
  const list = [];
  for (let i = layers.length - 1; i >= 0; i--) {
    const layer = layers[i];
    const kids = layer.layers;
    const nested = kids && kids.length ? hostLayers(kids) : undefined;
    list.push({
      id: layer.id,
      name: layer.name,
      kind: hostKind(layer),
      bounds: hostBounds(layer),
      layers: nested,
    });
  }
  return list;
}

function currentTreeFrame() {
  const doc = app.activeDocument;
  if (!doc) return null;
  return treeFrameFor({ name: doc.name, width: doc.width, height: doc.height }, hostLayers(doc.layers));
}

// -------------------------------------------------------------- the wire

function send(frame) {
  if (socket && socket.readyState === 1) socket.send(JSON.stringify(frame));
}

function flush() {
  flushTimer = null;
  const batch = coalesceEvents(pending);
  pending = [];
  batch.forEach((e) => {
    const frame = { type: 'event', change: e.change, props: e.props };
    if (e.layerID !== undefined) frame.layerID = e.layerID;
    send(frame);
    sentCount++;
  });
  if (batch.length) {
    info(`sent ${batch.length} change(s):`, batch.map((e) => e.change).join(', '));
    if (ui.sent) ui.sent.textContent = `${sentCount} change${sentCount === 1 ? '' : 's'} sent`;
  }
}

function scheduleFlush() {
  if (flushTimer === null) flushTimer = setTimeout(() => guard('flush', flush), FLUSH_MS);
}

/**
 * The layer a descriptor refers to, or null when it cannot be read confidently.
 *
 * VERIFY: this is the single most likely thing in the file to be wrong. A
 * WRONG id applies a real change to the wrong layer, which is the failure the
 * whole identity model exists to prevent -- so it returns null and the caller
 * sends nothing rather than guess. When it returns null it now LOGS the
 * descriptor, so the shape can be read off a real run instead of assumed.
 */
function layerIdFrom(descriptor) {
  const target = descriptor && descriptor._target;
  if (Array.isArray(target)) {
    for (let i = 0; i < target.length; i++) {
      const ref = target[i];
      if (ref && ref._ref === 'layer' && typeof ref._id === 'number') return ref._id;
    }
  }
  if (descriptor && typeof descriptor.layerID === 'number') return descriptor.layerID;
  if (descriptor && descriptor.layerID && typeof descriptor.layerID._id === 'number') return descriptor.layerID._id;
  return null;
}

/**
 * The payload for one change.
 *
 * Deliberately narrow: only the fields `CHANGE_MAP` names for that change reach
 * the wire. `validateEvent` does not police the inside of `props`, so this is
 * the last place a stray descriptor field can be stopped.
 *
 * VERIFY: every branch. These are the documented descriptor shapes; the raw
 * descriptor for each change kind is logged once per session so they can be
 * corrected against reality.
 */
function propsFor(change, descriptor, event) {
  const to = (descriptor && descriptor.to) || {};
  switch (change) {
    case 'move':
    case 'transform': {
      const layers = app.activeDocument && app.activeDocument.activeLayers;
      const b = layers && layers.length ? layers[0].bounds : null;
      if (!b) return {};
      const num = (v) => (typeof v === 'number' ? v : (v && typeof v._value === 'number' ? v._value : 0));
      const left = num(b.left), top = num(b.top);
      return { x: left, y: top, w: num(b.right) - left, h: num(b.bottom) - top };
    }
    case 'opacity': {
      const raw = to.opacity !== undefined ? to.opacity : to.fillOpacity;
      const pct = typeof raw === 'number' ? raw : (raw && typeof raw._value === 'number' ? raw._value : 100);
      return { opacity: pct / 100 };
    }
    case 'blendMode': {
      const mode = to.mode || to.blendMode;
      return { blendMode: String((mode && mode._value) || mode || 'normal') };
    }
    case 'visibility': {
      // `hide` and `show` say it in the event name; a `set` says it in `to`.
      if (event === 'hide') return { visible: false };
      if (event === 'show') return { visible: true };
      const v = to.visible !== undefined ? to.visible : descriptor.visible;
      if (typeof v !== 'boolean') return null;
      return { visible: v };
    }
    case 'rename': return { name: String(to.name == null ? '' : to.name) };
    case 'retype': return { text: to.textKey || {} };

    /**
     * REFUSED, not guessed.
     *
     * A reorder has to name the neighbour the layer now sits above, and that
     * is not something this plugin can read yet. The previous version sent
     * `belowLayerID: null`, which `reorderIndices` reads as "bottom of the
     * stack" -- so EVERY reorder moved the layer to the bottom, wherever it
     * had actually been dropped. That is a wrong edit applied to the right
     * layer, which is no better than the reverse.
     */
    case 'reorder': return null;

    /**
     * Also refused unless the rectangle is actually in the descriptor.
     *
     * After a crop, `doc.width`/`doc.height` are the size AFTER cropping, and
     * the offset is gone. Sending `{x: 0, y: 0, width, height}` would set the
     * app's frame to the full new size at the origin, which is only correct
     * for a crop that happened to start at 0,0.
     */
    case 'crop':
    case 'canvasSize': return rectFrom(descriptor);

    default: return {};
  }
}

/** A document rectangle from a descriptor, or null when it cannot be read. */
function rectFrom(descriptor) {
  const num = (v) => {
    if (typeof v === 'number') return v;
    if (v && typeof v._value === 'number') return v._value;
    return null;
  };
  const src = (descriptor && descriptor.to) || descriptor || {};
  const left = num(src.left), top = num(src.top), right = num(src.right), bottom = num(src.bottom);
  if ([left, top, right, bottom].every((v) => v !== null) && right > left && bottom > top) {
    return { x: left, y: top, width: right - left, height: bottom - top };
  }
  return null;
}

/**
 * One notification from Photoshop.
 *
 * The translation is `changeForNotification`'s, not this function's. All that
 * happens here is routing the three answers it can give: send it, count it as
 * undeliverable, or ignore it as something this protocol has no opinion on.
 */
function onNotification(event, descriptor) {
  if (!paired) return;

  // One raw descriptor per event name, so a real run documents the shapes
  // without a single drag printing two hundred lines.
  if (!sampled.has(event)) {
    sampled.add(event);
    let shape = '(unserialisable)';
    try { shape = JSON.stringify(descriptor).slice(0, 400); } catch { /* circular */ }
    info(`first "${event}" descriptor:`, shape);
  }

  const verdict = changeForNotification(event, descriptor);

  // Unknown is not the same as unmappable. An event we have never heard of is
  // not evidence that the user's work was dropped, so it is not reported as if
  // it were -- it is simply not ours.
  if (!verdict.known) return;

  if (!verdict.mappable) {
    noteSkipped(verdict.change);
    return;
  }

  const layerID = layerIdFrom(descriptor);
  const documentScoped = verdict.change === 'crop' || verdict.change === 'canvasSize';
  if (layerID === null && !documentScoped) {
    warn(`"${event}" -> ${verdict.change}, but no layer id could be read. Sending nothing.`);
    return;
  }

  // A null payload means "I could not build this without guessing". Sending a
  // guess would be a wrong edit applied to the right layer, which is no better
  // than the right edit applied to the wrong one -- so it is counted as not
  // synced, exactly like a brush stroke, and the reason is said out loud.
  const props = propsFor(verdict.change, descriptor, event);
  if (props === null) {
    noteSkipped(`${verdict.change} (payload not readable)`);
    warn(`"${event}" -> ${verdict.change}, but its payload could not be read from the descriptor. Sending nothing rather than a guess.`);
    if (!sampledPayload.has(verdict.change)) {
      sampledPayload.add(verdict.change);
      warn('descriptor was:', safeJson(descriptor).slice(0, 400));
    }
    return;
  }

  const entry = { change: verdict.change, props };
  if (!documentScoped) entry.layerID = layerID;
  pending.push(entry);
  scheduleFlush();
}

// ------------------------------------------------------------- lifecycle

/** Set once the first notification of any kind arrives. */
let heardAnything = false;

function subscribe() {
  // VERIFY-FIXED: plain strings, which is Adobe's documented form. The object
  // form the first version used subscribed to nothing at all.
  const result = action.addNotificationListener(WATCHED, (event, descriptor) => {
    if (!heardAnything) {
      heardAnything = true;
      // "Subscribed" is not the same as "receiving", and the difference is
      // invisible until something is expected and never comes. This line is
      // the proof that the subscription is real.
      good(`FIRST notification received ("${event}") — the subscription is live`);
    }
    guard('notification handler', () => onNotification(event, descriptor));
  });

  // The call may hand back a promise rather than a listener. Storing the
  // promise itself would make `listener.remove()` fail on teardown, quietly
  // leaving the subscription attached for the life of the panel.
  if (result && typeof result.then === 'function') {
    info('addNotificationListener returned a promise — resolving it');
    result.then(
      (resolved) => { listener = resolved; good(`subscribed to ${WATCHED.length} notification types`); },
      (e) => fail('addNotificationListener rejected:', e && e.message ? e.message : String(e)),
    );
    return null;
  }

  good(`subscribed to ${WATCHED.length} notification types`);
  info('now make an edit in Photoshop — a move or a rename — and watch for the FIRST notification line');
  return result;
}

function onPaired() {
  paired = true;
  if (watchdog !== null) { clearTimeout(watchdog); watchdog = null; }
  stage(6, "the relay accepted the code");
  const frame = guard('reading the document', currentTreeFrame);
  if (!frame) {
    setStatus('Paired, but no document could be read. Open the same file as the app.', 'failed');
    fail('currentTreeFrame() returned nothing — is a document open?');
    return;
  }
  send(frame);
  good(`sent tree: ${frame.document.name} ${frame.document.width}x${frame.document.height}, ${frame.layers.length} layers`);

  listener = guard('subscribing to notifications', subscribe);
  const n = frame.layers.length;
  setStatus(`Live — ${frame.document.name}, ${n} layer${n === 1 ? '' : 's'} sent.`, 'live');
}

function teardown(message, kind) {
  paired = false;
  if (watchdog !== null) { clearTimeout(watchdog); watchdog = null; }
  if (flushTimer !== null) { clearTimeout(flushTimer); flushTimer = null; }
  pending = [];
  if (listener && typeof listener.remove === 'function') guard('removing listener', () => listener.remove());
  listener = null;
  if (socket) {
    const s = socket;
    socket = null;
    guard('closing socket', () => s.close());
  }
  showConnected(false);
  setStatus(message, kind);
}

function onFrame(frame) {
  if (frame.type === 'paired') { guard('onPaired', onPaired); return; }
  if (frame.type === 'pair') { info('relay issued a code to the app side (not us)'); return; }
  if (frame.type === 'error') {
    fail(`relay refused: ${frame.code} — ${frame.message}`);
    teardown(`Relay refused: ${frame.message} (${frame.code})`, 'failed');
  }
}

/** JSON that cannot throw. Host objects are not always serialisable. */
function safeJson(value) {
  try { return JSON.stringify(value); } catch (e) { return `(unserialisable: ${e.message})`; }
}

/** Every layer in the tree, groups included — what the frame SHOULD contain. */
function countLayers(layers) {
  let n = 0;
  for (let i = 0; i < layers.length; i++) {
    n++;
    const kids = layers[i].layers;
    if (kids && kids.length) n += countLayers(kids);
  }
  return n;
}

// ------------------------------------------------------- staged progress

const STAGES = [
  '',
  'validating the address',
  'preflight to /whoami',
  'constructing the WebSocket',
  'socket open',
  'hello + pair sent',
  'paired',
];

let reachedStage = 0;
let watchdog = null;

function stage(n, note) {
  reachedStage = n;
  good(`[${n}/6] ${STAGES[n]}${note ? ' — ' + note : ''}`);
}

const READY_STATES = ['CONNECTING(0)', 'OPEN(1)', 'CLOSING(2)', 'CLOSED(3)'];
const readyStateName = (s) => {
  const v = s && typeof s.readyState === 'number' ? s.readyState : -1;
  return READY_STATES[v] || `unknown(${v})`;
};

/**
 * Say where it stalled, if it stalls.
 *
 * The worst failure to report is the silent one: a socket that neither opens
 * nor errors leaves every handler unfired, so nothing in the log marks the
 * end. This fires regardless and names the last stage reached, which turns
 * "nothing happened" into a specific accusation.
 */
function armWatchdog() {
  if (watchdog !== null) clearTimeout(watchdog);
  watchdog = setTimeout(() => {
    watchdog = null;
    if (reachedStage >= 6) return;
    fail(`STALLED at stage ${reachedStage}/6 — ${STAGES[reachedStage] || 'before anything'}`);
    if (socket) fail(`socket readyState is ${readyStateName(socket)}`);
    if (reachedStage === 3) {
      fail('the socket was constructed but never opened, errored or closed.');
      fail('that is a silent handshake rejection: almost always manifest.json network.domains not listing this exact host.');
    }
    if (reachedStage === 5) {
      fail('the relay never answered hello+pair. The code may be expired (5 minutes), already used, or wrong.');
    }
  }, 12000);
}

/**
 * Ask the relay what origin it received, and whether it would admit us.
 *
 * Fire and forget: the socket opens regardless, because this is a diagnostic,
 * not a gate. Whatever it prints -- including its own failure -- narrows the
 * problem from "cannot connect" to one specific cause.
 */
function preflight(wsUrl) {
  if (typeof fetch !== 'function') { warn('this runtime has no fetch — skipping the preflight; the socket will still be attempted'); return; }
  // Trailing slashes stripped, or a pasted address ending in "/" produces
  // "//whoami" and a 426 that looks like the route does not exist.
  const httpUrl = wsUrl.replace(/^ws/, 'http').replace(/\/+$/, '') + '/whoami';
  guard('preflight', () => {
    fetch(httpUrl)
      .then((res) => res.json())
      .then((body) => {
        info(`relay sees origin: ${JSON.stringify(body.origin)} · admitted: ${body.allowed}`);
        if (!body.allowed) {
          fail('THE RELAY WILL REFUSE THIS ORIGIN. The socket cannot open until it is allowed.');
          fail(body.hint || '');
        }
      })
      .catch((e) => {
        // Reaching /whoami and failing is different from not reaching it. If
        // this fails too, the address or network.domains is wrong -- not the
        // allowlist.
        warn(`preflight to ${httpUrl} failed: ${e && e.message ? e.message : String(e)}`);
        warn('if this failed, the problem is the address or manifest.json network.domains — not the origin');
      });
  });
}

/** True once a socket has actually opened, so a retry knows it is not needed. */
let everOpened = false;
/** The subprotocol retry has been spent. One experiment, not a loop. */
let triedSubprotocol = false;

function connect(protocol) {
  const url = ui.relay.value.trim();
  const code = ui.code.value.trim().toUpperCase();

  // Checked here as well as at the relay, because a typo should cost a glance
  // rather than one of ten attempts against the rate limit.
  const badChar = code.split('').filter((c) => PAIR_CODE_ALPHABET.indexOf(c) === -1);
  if (code.length !== PAIR_CODE_LENGTH || badChar.length) {
    setStatus(`That is not a pairing code — ${PAIR_CODE_LENGTH} characters from ${PAIR_CODE_ALPHABET}.`, 'failed');
    warn(`rejected code "${code}" locally: length ${code.length}, bad characters ${JSON.stringify(badChar)}`);
    return;
  }

  // Six stages, each announced. "It does not connect" is not a diagnosis; it
  // is six different diagnoses wearing the same sentence, and the only way to
  // tell them apart from outside is to say which one was reached.
  stage(1, `URL ${JSON.stringify(url)}`);

  if (!/^wss?:\/\//i.test(url)) {
    fail(`the relay address must start with ws:// or wss://, not ${JSON.stringify(url.split(':')[0])}`);
    setStatus('That is not a WebSocket address.', 'failed');
    return;
  }
  if (/\/$/.test(url)) warn('the address ends in a slash; that is usually harmless but not always');

  setStatus('Connecting…', 'working');

  // Ask the relay what it sees BEFORE opening the socket.
  //
  // A refused WebSocket upgrade reports nothing: a bare `error` event with no
  // status, no body, no reason. So "cannot connect" could equally be the
  // address, the network, `network.domains`, or the origin allowlist -- and
  // guessing between those is exactly where this plugin got stuck. One plain
  // HTTPS request answers it, and its failure is itself informative.
  stage(2, 'preflight to /whoami');
  preflight(url);

  stage(3, `constructing the WebSocket${protocol ? ` with subprotocol "${protocol}"` : ''}`);
  socket = guard('new WebSocket', () => (protocol ? new WebSocket(url, protocol) : new WebSocket(url)));
  if (!socket) {
    fail('new WebSocket(...) returned nothing or threw. See the line above.');
    setStatus('Could not create a socket. See the log.', 'failed');
    return;
  }
  info(`socket constructed · readyState ${readyStateName(socket)}`);

  const onOpen = () => guard('open handler', () => {
    everOpened = true;
    stage(4, `socket OPEN · readyState ${readyStateName(socket)}`);
    setStatus('Pairing…', 'working');
    send({ type: 'hello', role: 'plugin', version: PLUGIN_VERSION });
    send({ type: 'pair', code: code });
    stage(5, 'sent hello + pair — waiting for the relay to answer');
    showConnected(true);
  });

  const onMessage = (e) => guard('message handler', () => {
    let frame = null;
    const raw = e && e.data !== undefined ? e.data : e;
    try { frame = JSON.parse(raw); }
    catch { fail('a frame was not JSON:', String(raw).slice(0, 160)); return; }
    info(`recv ${frame.type}${frame.code ? ' ' + frame.code : ''}`);
    onFrame(frame);
  });

  const onClose = (e) => guard('close handler', () => {
    // The close code is the most informative thing a failed socket ever says.
    // 1006 means the connection died without a close frame -- which is what a
    // rejected upgrade looks like from the client side.
    const code = e && e.code !== undefined ? e.code : '(none)';
    const reason = e && e.reason ? e.reason : '(no reason given)';
    const clean = e && e.wasClean !== undefined ? e.wasClean : '(unknown)';
    fail(`socket CLOSED · code ${code} · reason ${JSON.stringify(reason)} · clean ${clean}`);
    if (code === 1006) fail('1006 means the upgrade was rejected or the connection dropped before a close frame — check the preflight line above');
    if (socket) teardown('Disconnected.', '');
  });

  const onError = (e) => guard('error handler', () => {
    // A failed handshake reaches here with no detail -- the security model
    // gives none -- so print whatever the event does carry rather than
    // asserting a cause.
    let detail = '';
    try {
      const bits = [];
      for (const k of ['message', 'type', 'code', 'reason', 'error']) {
        if (e && e[k] !== undefined) bits.push(`${k}=${JSON.stringify(String(e[k]))}`);
      }
      detail = bits.join(' ');
    } catch { /* the event may not be enumerable */ }
    fail(`socket ERROR ${detail || '(the event carried no detail — this is normal for a rejected upgrade)'}`);

    // ONE automatic experiment, rather than another guess.
    //
    // Adobe's own WebSocket example passes a subprotocol -- `new
    // WebSocket(url, "wss")` -- and if this runtime needs one, a socket opened
    // without it fails exactly like this: immediately, with an empty error.
    // Retrying once with it costs a second and turns a hypothesis into a
    // result either way. The relay echoes whatever is requested, so the
    // handshake cannot fail for want of confirmation.
    if (!everOpened && !triedSubprotocol) {
      triedSubprotocol = true;
      warn('retrying once WITH a subprotocol ("wss"), which is the form Adobe\'s own example uses…');
      socket = null;
      connect('wss');
      return;
    }

    fail('the causes, in order of likelihood:');
    fail('  1. the host is not in manifest.json network.domains — try plugin/manifest.all-domains.json to prove it');
    fail('  2. the relay refused the origin — see the preflight line above');
    fail('  3. the address or the network is wrong');
    teardown('Could not reach the relay. See the log.', 'failed');
  });

  // BOTH wiring styles. Adobe's documentation uses `ws.onopen = ...`, and
  // whether UXP's WebSocket also implements addEventListener is not something
  // to bet the whole connection on -- if it does not, the socket opens and no
  // handler ever runs, which looks exactly like "it will not connect".
  //
  // `wired` records which mechanism actually took, so a run says so rather
  // than leaving it to be guessed at again.
  const wired = [];
  try { socket.onopen = onOpen; socket.onmessage = onMessage; socket.onclose = onClose; socket.onerror = onError; wired.push('on* handlers'); }
  catch (e) { warn('assigning on* handlers threw:', e.message); }

  if (typeof socket.addEventListener === 'function') {
    // Guarded against double-firing: if on* took, these are the same calls
    // again. Both paths are idempotent -- `send` checks readyState, and
    // `teardown` clears `socket` first -- so a duplicate is harmless.
    wired.push('addEventListener');
  } else {
    warn('this WebSocket has no addEventListener — on* handlers are the only wiring, which is why both are attempted');
  }
  info(`socket wired via: ${wired.join(' + ') || 'NOTHING — no handler could be attached'}`);

  // If nothing has happened by now, say which stage it stalled at. A silent
  // socket is the hardest failure to report, because nothing fires at all.
  armWatchdog();
}

// ---------------------------------------------------------- diagnostics

/**
 * Turn the six assumptions into observations, in one click.
 *
 * Everything printed here is something the plugin currently GUESSES about the
 * host. Running it once on a real install is worth more than any amount of
 * further defensive coding, because a shape you have never seen cannot be
 * guarded against -- only guessed at again.
 */
function diagnose() {
  info('--- diagnostics ---');
  info('plugin', PLUGIN_VERSION, '· uxp', uxpVersion);

  guard('app.version', () => info('photoshop', app.version));

  const doc = guard('app.activeDocument', () => app.activeDocument);
  if (!doc) { warn('no active document — open a PSD and run this again'); return; }

  info(`document: "${doc.name}" ${doc.width}x${doc.height}, ${doc.layers.length} top-level layers`);

  guard('first layer shape', () => {
    const first = doc.layers[0];
    if (!first) { warn('the document has no layers'); return; }
    info('layer.id      ', typeof first.id, first.id);
    info('layer.name    ', typeof first.name, first.name);

    // `kind` is a LayerKind ENUM OBJECT, not a string. Printing the raw form
    // alongside what we reduce it to is how a wrong reduction becomes visible.
    info('layer.kind    ', `typeof=${typeof first.kind} raw=${safeJson(first.kind)} -> hostKind="${hostKind(first)}"`);

    // The bounds question that decides whether layers with effects match.
    let withEffects = '(threw)';
    let without = '(absent)';
    try { withEffects = safeJson(first.bounds); } catch (e) { withEffects = `(threw: ${e.message})`; }
    try { without = first.boundsNoEffects ? safeJson(first.boundsNoEffects) : '(absent on this build)'; } catch (e) { without = `(threw: ${e.message})`; }
    info('layer.bounds            ', withEffects, '  <- INCLUDES effects');
    info('layer.boundsNoEffects   ', without, '  <- what the app has, and what we send');
    if (withEffects !== without && without !== '(absent on this build)') {
      warn('the two differ on this layer, which is exactly why boundsNoEffects is used');
    }

    // Adobe documents `layers` as existing only on a group. Groups are
    // detected by its presence, so if a NON-group has it this assumption is
    // wrong and every layer would be classified as a group.
    info('layer.layers  ', first.layers === undefined ? 'undefined (good: not a group)' : `present, ${first.layers.length} children`);
  });

  guard('tree frame', () => {
    const frame = currentTreeFrame();
    if (!frame) { warn('currentTreeFrame() returned null'); return; }
    good(`tree frame builds: ${frame.layers.length} layers · bounds read from ${boundsUsed}`);
    info('first entry:', safeJson(frame.layers[0]));

    // A layer whose bounds could not be read is DROPPED by flattenLayerTree,
    // so a shortfall here means the app will never hear about those layers.
    const counted = countLayers(doc.layers);
    if (frame.layers.length !== counted) {
      warn(`${counted} layers in the document but ${frame.layers.length} in the frame — ${counted - frame.layers.length} had unreadable bounds and were dropped`);
    }
    const kinds = {};
    frame.layers.forEach((l) => { kinds[l.kind] = (kinds[l.kind] || 0) + 1; });
    info('kinds sent:', safeJson(kinds));
  });

  info('--- end diagnostics ---');
}

// ------------------------------------------------------------------ boot

function boot() {
  logbox = el('logbox');

  // Anything that escapes lands on screen. Without this a UXP panel that
  // throws during init is simply blank, with the reason only in a debugger
  // nobody has attached yet.
  try {
    if (typeof window === 'undefined') { warn('no window object — uncaught errors cannot be trapped on this runtime'); }
    else {
    window.addEventListener('error', (e) => fail('uncaught:', e.message || String(e)));
    window.addEventListener('unhandledrejection', (e) => fail('unhandled rejection:', (e.reason && e.reason.message) || String(e.reason)));
    }
  } catch { /* older UXP */ }

  ui = {
    status: el('status'), setup: el('setup'), live: el('live'),
    relay: el('relay'), code: el('code'),
    connect: el('connect'), disconnect: el('disconnect'),
    sent: el('sent'), unsynced: el('unsynced'),
    diagnose: el('diagnose'), copylog: el('copylog'), clearlog: el('clearlog'),
  };

  const missing = Object.keys(ui).filter((k) => !ui[k]);
  if (missing.length) fail('missing DOM elements:', missing.join(', '));

  info(`panel booted · plugin ${PLUGIN_VERSION}`);

  // What this runtime actually provides. Every one of these was assumed by
  // the first version, and a wrong assumption here is invisible: the code
  // runs, nothing happens, and nothing says why.
  info('capabilities:',
    'WebSocket=' + typeof WebSocket,
    'fetch=' + typeof fetch,
    'addEventListener=' + typeof document.addEventListener,
    'clipboard=' + (typeof navigator !== 'undefined' && navigator.clipboard ? 'yes' : 'no'));

  try {
    loadHost();
    good(`host modules loaded · uxp ${uxpVersion}`);
    setStatus('Not connected.', '');
  } catch (e) {
    fail("require('photoshop') failed:", e && e.message ? e.message : String(e));
    setStatus('Could not reach the Photoshop API. See the log.', 'failed');
  }

  if (ui.connect) ui.connect.addEventListener('click', () => guard('connect', () => { triedSubprotocol = false; everOpened = false; connect(); }));
  if (ui.disconnect) ui.disconnect.addEventListener('click', () => guard('disconnect', () => teardown('Disconnected.', '')));
  if (ui.diagnose) ui.diagnose.addEventListener('click', () => guard('diagnose', diagnose));
  if (ui.clearlog) ui.clearlog.addEventListener('click', () => { logLines.length = 0; clearChildren(logbox); });
  if (ui.copylog) {
    ui.copylog.addEventListener('click', () => guard('copy log', () => {
      const text = logLines.map((l) => l.line).join('\n');
      let copied = false;
      try { navigator.clipboard.setContent({ 'text/plain': text }); copied = true; } catch { /* try the other shape */ }
      if (!copied) { try { navigator.clipboard.writeText(text); copied = true; } catch { /* neither */ } }
      info(copied ? 'log copied to the clipboard' : 'clipboard unavailable — select the log text instead');
    }));
  }

  renderSkipped();
}

boot();
